const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);

export default function FoundationWallCapsPanel({ caps = [], walls = [], options = [], onChange }) {
  const patchCap = (index, changes) =>
    onChange(caps.map((c, i) => (i === index ? { ...c, ...changes } : c)));

  const removeCap = (index) => {
    if (!window.confirm(`Remove cap ${index + 1}?`)) return;
    onChange(caps.filter((_, i) => i !== index));
  };

  const addCap = () => {
    const inv = options[0];
    onChange([
      ...caps,
      {
        id: `cap_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
        cap_inventory_id: inv?.id || "",
        wall_component_id: walls[0]?.component_id || "",
        wall_index: walls.length ? 0 : undefined,
        segment_component_id: walls[0]?.shape?.segments?.[0]?.component_id || "",
        segment_index: walls[0]?.shape?.segments?.length ? 0 : undefined,
        position_along_segment_inches: 0,
        length_inches: num(inv?.cap_stock_length_inches) || 48,
        rotation_offset_degrees: 0,
        lateral_offset_inches: 0,
      },
    ]);
  };

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="font-semibold text-gray-900">Wall Caps</h2>
          <p className="text-xs text-gray-500">Full stock price is charged per cut piece.</p>
        </div>
        <Button variant="outline" size="sm" onClick={addCap} disabled={options.length === 0}>
          <Plus className="w-4 h-4" aria-hidden="true" /> Cap
        </Button>
      </div>

      {options.length === 0 && (
        <div className="text-[11px] text-amber-800 bg-amber-50 border border-amber-200 rounded px-2 py-1.5">
          Wall cap catalog unavailable — existing rows remain editable; new caps cannot be added.
        </div>
      )}
      {caps.length === 0 ? (
        <div className="text-center py-6 bg-white rounded-xl border border-dashed border-gray-300 text-gray-500 text-sm">
          No caps on this section.
        </div>
      ) : (
        caps.map((cap, index) => (
          <div key={cap.component_id || cap.id || index} className="bg-white rounded-xl border border-gray-200 p-3">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-2 items-end">
              <label className="text-xs text-gray-500 md:col-span-2">
                Cap material
                <select
                  className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                  value={cap.cap_inventory_id || ""}
                  aria-label="Cap material"
                  onChange={(e) => {
                    const inv = options.find((o) => o.id === e.target.value);
                    patchCap(index, {
                      cap_inventory_id: e.target.value,
                      length_inches: num(inv?.cap_stock_length_inches) || cap.length_inches,
                    });
                  }}
                >
                  <option value="">Select cap…</option>
                  {cap.cap_inventory_id && !options.some((o) => o.id === cap.cap_inventory_id) && (
                    <option value={cap.cap_inventory_id} disabled>{`Catalog cap unavailable (${cap.cap_inventory_id})`}</option>
                  )}
                  {options.map((o) => (
                    <option key={o.id} value={o.id}>
                      {o.material_name}
                    </option>
                  ))}
                </select>
                {cap.cap_inventory_id && !options.some((o) => o.id === cap.cap_inventory_id) && (
                  <span className="block text-[10px] text-amber-700 mt-1">Catalog cap unavailable; current pricing needs review.</span>
                )}
              </label>
              <label className="text-xs text-gray-500">
                Wall
                <select
                  className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                  value={cap.wall_component_id ?? ""}
                  aria-label="Cap wall"
                  onChange={(e) => {
                    const id = e.target.value;
                    const i = walls.findIndex((w) => w.component_id === id);
                    patchCap(index, {
                      wall_component_id: id,
                      wall_index: id === "" || i < 0 ? undefined : i,
                      segment_component_id: "",
                      segment_index: undefined,
                    });
                  }}
                >
                  <option value="">Unassigned</option>
                  {cap.wall_component_id && !walls.some((w) => w.component_id === cap.wall_component_id) && (
                    <option value={cap.wall_component_id} disabled>{`Missing wall (${String(cap.wall_component_id).slice(0, 18)}…)`}</option>
                  )}
                  {walls.map((w, i) => (
                    <option key={w.component_id || i} value={w.component_id || ""}>
                      {w.name || `Wall ${i + 1}`}
                    </option>
                  ))}
                </select>
              </label>
              <label className="text-xs text-gray-500">
                Segment
                <select
                  className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                  value={cap.segment_component_id ?? ""}
                  aria-label="Cap segment"
                  onChange={(e) => {
                    const id = e.target.value;
                    const wall = walls.find((w) => w.component_id === cap.wall_component_id);
                    const segs = wall?.shape?.segments || [];
                    const i = segs.findIndex((sg) => sg.component_id === id);
                    patchCap(index, {
                      segment_component_id: id,
                      segment_index: id === "" || i < 0 ? undefined : i,
                    });
                  }}
                >
                  <option value="">Unassigned</option>
                  {cap.segment_component_id && !(walls.find((w) => w.component_id === cap.wall_component_id)?.shape?.segments || []).some((sg) => sg.component_id === cap.segment_component_id) && (
                    <option value={cap.segment_component_id} disabled>{`Missing segment (${String(cap.segment_component_id).slice(0, 18)}…)`}</option>
                  )}
                  {(walls.find((w) => w.component_id === cap.wall_component_id)?.shape?.segments || []).map((sg, i) => (
                    <option key={sg.component_id || i} value={sg.component_id || ""}>
                      {`Segment ${i + 1}`}
                    </option>
                  ))}
                </select>
              </label>
              <label className="text-xs text-gray-500">
                Cut length (in)
                <Input
                  type="number"
                  value={cap.length_inches ?? 48}
                  onChange={(e) => patchCap(index, { length_inches: Math.max(1, num(e.target.value)) })}
                />
              </label>
            </div>
            <div className="flex items-center justify-between mt-2 text-xs text-gray-600">
              <span>
                Stock length: <span className="font-semibold text-gray-900">{cap.stock_length_inches || 0}"</span>
              </span>
              <div className="flex items-center gap-3">
                <span className="font-bold text-gray-900">{money(cap.cost)}</span>
                <Button variant="ghost" size="icon" onClick={() => removeCap(index)}>
                  <Trash2 className="w-4 h-4 text-red-500" aria-hidden="true" />
                </Button>
              </div>
            </div>
          </div>
        ))
      )}
    </div>
  );
}

import React from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Trash2, Plus, PenLine } from "lucide-react";
import { money } from "./foundationCalc";
import WallShapeEditor from "./WallShapeEditor";

const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);

function WallRow({ wall, index, options, onChange, onRemove }) {
  const c = wall.calculatedCosts || {};
  const set = (changes) => onChange(index, changes);
  const [showEditor, setShowEditor] = React.useState(false);

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-3 space-y-3">
      <div className="flex items-center justify-between gap-2">
        <Input
          className="max-w-[220px]"
          value={wall.name || ""}
          placeholder={`Wall ${index + 1}`}
          onChange={(e) => set({ name: e.target.value })}
        />
        <div className="flex items-center gap-3">
          <span className="font-bold text-gray-900">{money(c.totalCost)}</span>
          <Button variant="ghost" size="icon" onClick={() => onRemove(index)}>
            <Trash2 className="w-4 h-4 text-red-500" aria-hidden="true" />
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
        <label className="text-xs text-gray-500">
          Height (in)
          <Input
            type="number"
            value={wall.heightInches ?? 24}
            onChange={(e) => set({ heightInches: num(e.target.value) })}
          />
        </label>
        <label className="text-xs text-gray-500">
          Mortar gap (in)
          <Input
            type="number"
            step="0.125"
            value={wall.mortarGapInches ?? 0.375}
            onChange={(e) => set({ mortarGapInches: num(e.target.value) })}
          />
        </label>
        <label className="text-xs text-gray-500 md:col-span-2">
          Wall material
          <select
            className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
            value={wall.materialId || ""}
            aria-label="Wall material"
            onChange={(e) => set({ materialId: e.target.value })}
          >
            <option value="">Select material…</option>
            {wall.materialId && !options.some((o) => o.id === wall.materialId) && (
              <option value={wall.materialId} disabled>{`Catalog material unavailable (${wall.materialId})`}</option>
            )}
            {options.map((o) => (
              <option key={o.id} value={o.id}>
                {o.material_name}
              </option>
            ))}
          </select>
          {wall.materialId && !options.some((o) => o.id === wall.materialId) && (
            <span className="block text-[10px] text-amber-700 mt-1">Catalog material unavailable; current pricing needs review.</span>
          )}
        </label>
      </div>

      <div className="rounded-lg bg-slate-50 p-2 space-y-2">
        <label className="flex items-center gap-2 text-xs font-medium text-gray-700">
          <input
            type="checkbox"
            checked={!!wall.includeInternalWall}
            onChange={(e) => set({ includeInternalWall: e.target.checked })}
          />
          Internal fill wall
        </label>
        {wall.includeInternalWall && (
          <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
            <label className="text-xs text-gray-500 md:col-span-2">
              Fill material
              <select
                className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                value={wall.internalMaterialId || ""}
                aria-label="Internal wall material"
                onChange={(e) => set({ internalMaterialId: e.target.value })}
              >
                <option value="">Select material…</option>
                {wall.internalMaterialId && !options.some((o) => o.id === wall.internalMaterialId) && (
                  <option value={wall.internalMaterialId} disabled>{`Catalog material unavailable (${wall.internalMaterialId})`}</option>
                )}
                {options.map((o) => (
                  <option key={o.id} value={o.id}>
                    {o.material_name}
                  </option>
                ))}
              </select>
              {wall.internalMaterialId && !options.some((o) => o.id === wall.internalMaterialId) && (
                <span className="block text-[10px] text-amber-700 mt-1">Catalog material unavailable; current pricing needs review.</span>
              )}
            </label>
            <label className="text-xs text-gray-500">
              Fill height (in)
              <Input
                type="number"
                value={wall.internalWallHeightInches ?? wall.heightInches ?? 24}
                onChange={(e) => set({ internalWallHeightInches: num(e.target.value) })}
              />
            </label>
          </div>
        )}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-2 text-xs text-gray-600">
        <div>Units: <span className="font-semibold text-gray-900">{Math.round(num(c.totalBricks))}</span></div>
        <div>Courses: <span className="font-semibold text-gray-900">{Math.ceil(num(c.numCourses))}</span></div>
        <div>Material: <span className="font-semibold text-gray-900">{money(c.materialCost)}</span></div>
        <div>Mortar: <span className="font-semibold text-gray-900">{money(c.mortarCost)}</span></div>
        <div>Labor: <span className="font-semibold text-gray-900">{money(c.laborCost)}</span></div>
        <div>Labor hrs: <span className="font-semibold text-gray-900">{num(c.laborHours).toFixed(1)}</span></div>
        <div>Linear in: <span className="font-semibold text-gray-900">{Math.round(num(c.totalLinearInches))}</span></div>
      </div>

      <div className="flex items-center gap-2">
        <Button variant="outline" size="sm" onClick={() => setShowEditor((v) => !v)}>
          <PenLine className="w-4 h-4" aria-hidden="true" /> {showEditor ? "Hide outline" : "Wall outline"}
        </Button>
        {!wall.shape?.segments?.length && (
          <span className="text-xs text-amber-600">
            No outline yet — this wall stays at $0 until its footprint is drawn.
          </span>
        )}
      </div>

      {showEditor && (
        <WallShapeEditor shape={wall.shape} onChange={(shape) => set({ shape })} />
      )}
    </div>
  );
}

export default function FoundationWallsPanel({ walls = [], options = [], onChange }) {
  const patchWall = (index, changes) =>
    onChange(walls.map((w, i) => (i === index ? { ...w, ...changes } : w)));

  const removeWall = (index) => {
    const name = walls[index]?.name || `Wall ${index + 1}`;
    if (!window.confirm(`Remove ${name}? Wall caps attached to it are retained for review.`)) return;
    onChange(walls.filter((_, i) => i !== index));
  };

  const addWall = () =>
    onChange([
      ...walls,
      { name: `Wall ${walls.length + 1}`, heightInches: 24, mortarGapInches: 0.375, offsetFraction: 0.5 },
    ]);

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <h2 className="font-semibold text-gray-900">Masonry Walls</h2>
        <Button variant="outline" size="sm" onClick={addWall}>
          <Plus className="w-4 h-4" aria-hidden="true" /> Wall
        </Button>
      </div>

      {walls.length === 0 ? (
        <div className="text-center py-8 bg-white rounded-xl border border-dashed border-gray-300 text-gray-500 text-sm">
          No walls on this section.
        </div>
      ) : (
        walls.map((wall, index) => (
          <WallRow
            key={wall.component_id || index}
            wall={wall}
            index={index}
            options={options}
            onChange={patchWall}
            onRemove={removeWall}
          />
        ))
      )}
    </div>
  );
}
